async function downloadSinglePagePdf(html,filename,selector,kind){
 const frame=document.createElement("iframe");
 frame.setAttribute("aria-hidden","true");
 frame.style.cssText="position:fixed;left:-12000px;top:0;width:816px;height:1200px;border:0;opacity:0;pointer-events:none";
 document.body.appendChild(frame);
 try{
  const loaded=new Promise((resolve,reject)=>{frame.addEventListener("load",resolve,{once:true});setTimeout(()=>reject(new Error("The document preview did not finish loading.")),10000)});
  let pdfHtml=html;
  frame.contentWindow?.document?.open();
  frame.contentWindow?.document?.write(pdfHtml);
  frame.contentWindow?.document?.close();
  await loaded;
  const doc=frame.contentDocument;
  if(!doc)throw new Error("Could not prepare the PDF document.");
  if(doc.fonts?.ready)await doc.fonts.ready;
  await Promise.all(Array.from(doc.images||[]).map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.onload=resolve;img.onerror=resolve;setTimeout(resolve,4000)})));
  await new Promise(resolve=>setTimeout(resolve,180));
  const el=doc.querySelector(selector);
  if(!el)throw new Error("Could not find the document content to export.");
  doc.documentElement.style.cssText="margin:0!important;padding:0!important;background:#fff!important;width:816px!important";
  doc.body.style.cssText+=";margin:0!important;padding:0!important;background:#fff!important;width:816px!important";
  el.style.transform="none";el.style.zoom="1";el.style.overflow="visible";
  if(kind==="trade"){
   const page=doc.getElementById("printPage");
   if(page){page.style.height="auto";page.style.maxHeight="none";page.style.overflow="visible";page.style.width="100%"}
   el.style.width="100%";
  }else{el.style.width="8.14in";el.style.height="auto";el.style.minHeight="0";el.style.margin="0";el.style.overflow="visible"}
  el.style.removeProperty(kind==="trade"?"--trade-size":"--invoice-size");
  const targetHeight=10.55*96;
  let low=6.5,high=kind==="trade"?19:18,best=low;
  const setSize=size=>doc.body.style.setProperty(kind==="trade"?"--trade-size":"--invoice-size",size+"px");
  for(let i=0;i<20;i++){const mid=(low+high)/2;setSize(mid);const h=Math.max(el.scrollHeight,el.getBoundingClientRect().height);if(h<=targetHeight){best=mid;low=mid}else{high=mid}}
  setSize(best);
  await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
  const canvas=await html2canvas(el,{scale:2,backgroundColor:"#ffffff",useCORS:true,allowTaint:false,logging:false,windowWidth:816,windowHeight:Math.max(1200,el.scrollHeight+80),scrollX:0,scrollY:0});
  if(!canvas.width||!canvas.height)throw new Error("The PDF renderer returned an empty page.");
  const pdf=new jsPDF({orientation:"portrait",unit:"pt",format:"letter",compress:true});
  const margin=12,pageW=pdf.internal.pageSize.getWidth(),pageH=pdf.internal.pageSize.getHeight();
  pdf.addImage(canvas,"PNG",margin,margin,pageW-margin*2,pageH-margin*2,undefined,"FAST");
  pdf.save(filename);
 }catch(err){console.error("PDF download failed:",err);alert("Could not download the PDF. Please try again. "+String(err?.message||err))}
 finally{frame.remove()}
}

